function demoMain(idx,label){
  var msgs=["secret1","hello world","topsecret"];
  var m=msgs[idx%msgs.length];var key=7;
  var enc=m.split("").map(function(c){return String.fromCharCode(c.charCodeAt(0)+key);}).join("");
  var dec=enc.split("").map(function(c){return String.fromCharCode(c.charCodeAt(0)-key);}).join("");
  return "["+label+"] encrypted '"+m+"' -> '"+enc+"' -> decrypted '"+dec+"' ("+(dec===m?"OK":"FAIL")+")";
}

